insert into public.commercial_policy_versions (id, version, title, effective_from, status) values
  ('df8df587-3b8c-483b-a472-78bfafb7cc55', '1.2', 'Política Comercial da Fábrica', null, 'active')
insert into public.commercial_policy_sections (id, policy_version_id, section_number, title, content, is_pending, display_order) values
  ('a6b6c499-b674-4c1f-aa0a-6e5a43111cc0', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '1', 'Objetivo', 'Regras comerciais das vendas diretas da fábrica Qualinutri: condições de pagamento, descontos por linha, prazos de produção e entrega, retirada, crédito, frete e logística. Objetivo: padronizar o atendimento e assegurar rentabilidade e previsibilidade.', false, 0),
  ('776bdc7f-b0b3-4061-a008-3e471fec72a6', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '2', 'Abrangência', 'Toda a equipe comercial, administrativa, de produção e de logística, e todas as vendas diretas da fábrica. Cumprimento obrigatório.', false, 1),
  ('0b5de43b-c926-4ea0-aeaf-84dafc5e5947', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '3', 'Tabela de preços', 'Preços conforme as Tabelas vigentes — Rações e Mineral/Proteinado/Núcleos (a partir de 03/09/2026), em R$ por saca. O preço “à vista” é a base para descontos e antecipações. Prevalece a tabela vigente na data do pedido.', false, 2),
  ('43517f8b-bfca-4cdb-af27-537eb904da21', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '4', 'Condições de pagamento', 'À vista antecipado: +1,5% sobre o preço à vista. Havendo estoque, a retirada pode ser feita; não havendo, produção em até 15 dias. À vista: até 15 dias. A prazo: 30; 30/60 ou 45; 30/60/90 ou 60; 30/60/90/120 ou 75; 30/60/90/120/150 ou 90 dias — conforme a tabela.', false, 3),
  ('b49e8e93-6bd8-4fc2-acbb-9bc907471e83', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '5', 'Descontos por linha', 'Ver a tabela de descontos. Aplicado sobre o preço de tabela, independente do pagamento. Frete e descarga sem desconto. Promoções podem mudar a qualquer momento. Acúmulo do 1,5% com o desconto de linha: só com aprovação do Gestor Comercial e da Diretoria.', false, 4),
  ('43bbab35-7cc7-4e51-aef7-4ebb02c12e37', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '6', 'Política de crédito', '<span class=''todo''>A definir.</span> Sem política de crédito oficializada. Novos clientes: à vista/antecipado até formar histórico; prazo caso a caso. A definir: critérios/limites, documentação e alçadas.', true, 5),
  ('fd63e353-de76-4446-a52c-74c1f002a6e1', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '7', 'Pedido mínimo', 'O pedido mínimo é de <b>1 tonelada</b>.', false, 6),
  ('d6d82e24-62ed-46f3-a4f2-b2a3bd7847b7', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '8', 'Pedidos e confirmação', 'Pedidos por telefone e WhatsApp. Pedido por telefone confirmado por escrito no WhatsApp. Faturamento após confirmação e validação de cadastro.', false, 7),
  ('1f81eaec-f6b9-426f-a7f5-4853a836edc6', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '9', 'Produção e prazos de entrega', 'Em estoque: expedição conforme programação. Sem estoque: produção em até 15 dias. Prazos informados na confirmação.', false, 8),
  ('70d5abd9-5a13-4e92-a6b4-f8c0018275d0', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '10', 'Retirada de produtos (compra de retirada)', 'Na compra de retirada, o cliente tem até 6 meses para retirar o produto na fábrica. Após os 6 meses, para manter armazenado, cobra-se <b>R$ 1,00 por saco ao mês</b>.', false, 9),
  ('02c076de-ec59-42d8-aa69-61870b8d2815', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '11', 'Frete e logística', 'Fácil acesso: freteiro terceirizado. Difícil acesso: frota própria. Os valores seguem as Tabelas de Frete vigentes (Juara e Regional — 06/05/2026), na aba “Frete”. Frete e descarga sem desconto. Carga fechada = uma única entrega (10/18/28 t); fracionada = mais de uma entrega. Descarga por conta do cliente; produto descarregado acresce R$ 40,00/tonelada. Entrega mínima 1.000 kg por cliente. Conversão: ração = 25 sacos/t; mineral/proteico/núcleos = 33,33 sacos/t; concentrado 130/160 = 40 sacos/t.', false, 10),
  ('642516cb-a172-4cb7-a433-9ffda540ca68', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '12', 'Devoluções e trocas', 'Solicitações com nota fiscal; avarias registradas no recebimento. <span class=''todo''>A definir:</span> prazo para solicitação.', true, 11),
  ('a32e85f2-2227-42a8-a9c8-13626268ed31', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '13', 'Responsabilidades', 'Gestor Comercial/Diretoria: aprovações, alçadas e casos omissos. Comercial: cadastro, pedidos e aplicação de tabela/descontos. Cibelly: estoque e custo de frete/margens. Rogério: compras e manutenção da frota. Produção: prazo de 15 dias e controle das retiradas.', false, 12),
  ('3c98e137-d538-4ffc-a142-2f655527d9da', 'df8df587-3b8c-483b-a472-78bfafb7cc55', '14', 'Vigência e revisão', 'Em vigor a partir da aprovação, por prazo indeterminado. Revisão a cada mudança de tabela/condições ou, no mínimo, anual. Aprovada pelo Gestor Comercial e pela Diretoria.', false, 13)
